  JellyfinBrowser(MainActivity a){super(a);this.a=a;ra=a.jellyfin;setFocusableInTouchMode(true);ra.changed=()->{int selected=index,scroll=offset;build();index=Math.min(selected,Math.max(0,rows.size()-1));offset=Math.min(scroll,Math.max(0,rows.size()-slots()));invalidate();};hub();}
