  String subtitle(JSONObject item){String s=item.optString("Type");switch(s){case "CollectionFolder":s="Library";break;case "MusicAlbum":s="Album";break;case "MusicArtist":s="Artist";break;case "Series":s="TV series";break;case "MusicVideo":s="Music video";break;}if(item.has("ProductionYear"))s+=" · "+item.optInt("ProductionYear");long ticks=item.optLong("RunTimeTicks");if(ticks>0)s+=" · "+(ticks/600000000L)+" min";return s;}
  void users(){ra.get("/Users",value->{if(value instanceof JSONArray){history.clear();entries=(JSONArray)value;listTitle="Choose "+ra.name()+" Profile";listPath="";startIndex=0;total=entries.length();page(6);}});}
  void libraries(){if(ra.user().isEmpty()){users();return;}history.clear();load("Libraries","/Users/"+ra.user()+"/Views",0,false);}
  void load(String title,String path,int start,boolean push){if(ra.user().isEmpty()){users();return;}final Location previous=new Location();previous.entries=entries;previous.title=listTitle;previous.path=listPath;previous.start=startIndex;previous.total=total;previous.index=index;previous.offset=offset;final boolean remember=push&&screen==2;String request=path+(path.contains("?")?"&":"?")+"StartIndex="+start+"&Limit=100&Fields=Overview,MediaSources&EnableUserData=true&SortBy=SortName&SortOrder=Ascending";ra.get(request,value->{if(!(value instanceof JSONObject))return;JSONObject result=(JSONObject)value;if(remember)history.push(previous);entries=result.optJSONArray("Items");if(entries==null)entries=new JSONArray();total=result.optInt("TotalRecordCount",entries.length());startIndex=start;listTitle=title;listPath=path;page(2);});}
  void refresh(){if(screen==8)return;if(screen==2)load(listTitle,listPath,startIndex,false);else if(screen==6)users();else libraries();}
  void edit(String title,String initial,boolean secret,java.util.function.Consumer<String> save){boolean wasSecure=(a.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_SECURE)!=0;if(secret)a.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);a.tools.editor=new BladesKeyboard(a,title,initial,secret?2048:256,false,v->{save.accept(v);build();invalidate();},()->{a.tools.editor=null;if(secret&&!wasSecure)a.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SECURE);post(this::requestFocus);});a.tools.editor.secret=secret;}
  void pasteKey(){android.content.ClipboardManager cb=(android.content.ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE);ClipData clip=cb.getPrimaryClip();if(clip!=null&&clip.getItemCount()>0&&clip.getItemAt(0).getText()!=null)ra.key(clip.getItemAt(0).getText().toString());}
  void play(){String type=selected.optString("MediaType",selected.optString("Type"));if(!Arrays.asList("Video","Audio","Movie","Episode","MusicVideo","Photo").contains(type)){ra.status="This item is not playable media";invalidate();return;}a.media.pauseMusic();player=new JellyfinPlayer(this,selected);a.addContentView(player,new ViewGroup.LayoutParams(-1,-1));player.requestFocus();}
  void back(){ra.cancel();if(player!=null){player.close();return;}if(screen==8)close();else if(screen==0)hub();else if(screen==3)page(2);else if(screen==7)page(4);else if(screen==2&&!history.isEmpty()){Location p=history.pop();entries=p.entries;listTitle=p.title;listPath=p.path;startIndex=p.start;total=p.total;screen=2;index=p.index;offset=p.offset;build();invalidate();}else home();}
  void close(){closed=true;ra.cancel();ra.changed=()->{};if(player!=null)player.close();if(getParent() instanceof ViewGroup)((ViewGroup)getParent()).removeView(this);a.jellyfinBrowser=null;a.dashboard.requestFocus();}
  int slots(){return Math.max(3,Math.min(9,(int)((height-300)/61)));}
  void move(int n){index=Math.max(0,Math.min(rows.size()-1,index+n));if(index<offset)offset=index;if(index>=offset+slots())offset=index-slots()+1;invalidate();}
  void select(){if(index>=0&&index<rows.size())rows.get(index).run.run();invalidate();}
  @Override public boolean onKeyDown(int key,KeyEvent e){if(e.getRepeatCount()>0&&(key==96||key==97))return true;switch(key){case 19:move(-1);break;case 20:move(1);break;case 102:move(-slots());break;case 103:move(slots());break;case 96:case 66:case 23:select();break;case 97:case 4:back();break;case 99:if(screen!=8)page(4);break;case 100:refresh();break;}return true;}
  @Override public boolean onKeyUp(int key,KeyEvent e){return true;}
  @Override public boolean onGenericMotionEvent(MotionEvent e){float y=e.getAxisValue(16);if(Math.abs(y)<.5f)y=e.getAxisValue(1);long now=android.os.SystemClock.uptimeMillis();if(Math.abs(y)<.5f){stick=0;return true;}if(now-stick>180){move(y>0?1:-1);stick=now;}return true;}
  void text(Canvas c,String s,float x,float y,float size,int color){p.setShader(null);p.setColor(color);p.setTypeface(a.dashboard.regular);p.setTextSize(size);c.drawText(s,x,y,p);}
  String fit(String s,float width,float size){p.setTypeface(a.dashboard.regular);p.setTextSize(size);if(p.measureText(s)<=width)return s;int n=s.length();while(n>0&&p.measureText(s.substring(0,n)+"…")>width)n--;return s.substring(0,n)+"…";}
