    for(int i=offset;i<Math.min(rows.size(),offset+slots());i++){float y=215+(i-offset)*61;Item item=rows.get(i);if(i==index)gradient(c,new RectF(123,y-2,669,y+56),0xffe8f5fa,0xff9cc5df,10);text(c,fit(item.title,500,25),140,y+25,25,0xff17344e);text(c,fit(item.sub,500,18),140,y+48,18,0xff315772);p.setColor(0x55496c85);c.drawLine(132,y+59,662,y+59,p);}
